<?php
$active_module='invoices'; require_once __DIR__.'/layout.php'; $u=$supplier_user;$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$number=trim((string)($_POST['invoice_number']??''));$customer=trim((string)($_POST['customer_name']??''));$subtotal=(float)str_replace(',','.',$_POST['subtotal']??0);$tax=(float)str_replace(',','.',$_POST['tax_rate']??20);$currency=$_POST['currency']??'TRY';if($number===''||$customer===''||$subtotal<0||$tax<0||$tax>100){$error='Fatura numarası, müşteri ve tutar bilgilerini kontrol edin.';}else{$taxAmount=round($subtotal*$tax/100,2);$total=$subtotal+$taxAmount;try{$pdo->prepare('INSERT INTO supplier_invoices (supplier_id,invoice_number,customer_name,customer_tax_number,issue_date,due_date,subtotal,tax_rate,tax_amount,total_amount,currency,status) VALUES (?,?,?,?,?,?,?,?,?,?,?,"draft")')->execute([$u['supplier_id'],$number,$customer,trim((string)($_POST['customer_tax_number']??''))?:null,$_POST['issue_date']??date('Y-m-d'),$_POST['due_date']?:null,$subtotal,$tax,$taxAmount,$total,in_array($currency,['TRY','EUR','USD','GBP','RUB','AED'],true)?$currency:'TRY']);header('Location: /nexustraveltech/tedarikci/faturalama?created=1');exit;}catch(Throwable $e){$error='Bu fatura numarası daha önce kullanılmış olabilir.';}}}
$q=$pdo->prepare('SELECT * FROM supplier_invoices WHERE supplier_id=? ORDER BY issue_date DESC,id DESC LIMIT 50');$q->execute([$u['supplier_id']]);$invoices=$q->fetchAll();supply_start('Muhasebe & faturalama', $active_module); ?>
<section class="page-intro"><p>Rezervasyona bağlı satış, komisyon ve iade kayıtlarını buradan takip edin. E-belge entegrasyonu aktifleştiğinde taslak kayıtlar mali sisteme iletilecek.</p></section><?php if(isset($_GET['created'])): ?><p class="save-success">✓ Fatura taslağı oluşturuldu.</p><?php endif; ?><?php if($error): ?><p class="login-error"><?= htmlspecialchars($error) ?></p><?php endif; ?>
<section class="invoice-grid"><form method="post" class="invoice-form"><h2>Yeni fatura taslağı</h2><label>Fatura numarası<input name="invoice_number" required placeholder="Örn. SAT-2026-0001"></label><label>Müşteri / acente ünvanı<input name="customer_name" required></label><label>Vergi no / TCKN<input name="customer_tax_number"></label><div class="form-row"><label>Düzenleme tarihi<input type="date" name="issue_date" value="<?= date('Y-m-d') ?>"></label><label>Vade<input type="date" name="due_date"></label></div><div class="form-row"><label>Ara toplam<input type="number" name="subtotal" min="0" step="0.01" required></label><label>KDV (%)<input type="number" name="tax_rate" min="0" max="100" step="0.01" value="20"></label></div><label>Para birimi<select name="currency"><option>TRY</option><option>EUR</option><option>USD</option><option>GBP</option><option>RUB</option><option>AED</option></select></label><button type="submit">Taslak fatura oluştur →</button></form><article class="invoice-list"><div class="panel-title"><div><span>SON FATURALAR</span><h2>Muhasebe kayıtları</h2></div></div><?php if(!$invoices): ?><p class="empty-state">Henüz fatura taslağı yok.</p><?php endif; ?><?php foreach($invoices as $invoice): ?><div class="invoice-row"><div><b><?= htmlspecialchars($invoice['invoice_number']) ?></b><span><?= htmlspecialchars($invoice['customer_name']) ?> · <?= htmlspecialchars($invoice['issue_date']) ?></span></div><strong><?= number_format((float)$invoice['total_amount'],2,',','.') ?> <?= htmlspecialchars($invoice['currency']) ?></strong><em><?= htmlspecialchars($invoice['status']) ?></em></div><?php endforeach; ?></article></section><?php supply_end(); ?>
